import { motion } from 'framer-motion';
import { TypeAnimation } from 'react-type-animation';
import { FaGithub, FaLinkedin, FaTwitter, FaDownload } from 'react-icons/fa';
import { HiOutlineMail } from 'react-icons/hi';
import heroImage from '../assets/images/hero.jpg';
import resumePDF from '../assets/images/ShahzaibAbbasi-Resume.pdf';import React from 'react';
import Services from '../components/home/Services';
import StatsCounter from '../components/home/StatsCounter';
import TechCarousel from '../components/home/TechCarousel';
import ProjectShowcase from '../components/home/ProjectShowcase';
import Testimonials from '../components/home/Testimonials';
import ContactCTA from '../components/home/ContactCTA';



const Home = ({ theme }) => {
  const socialLinks = [
    { icon: <FaGithub />, url: "https://github.com/shahzaib-abbasi", name: "GitHub" },
    { icon: <FaLinkedin />, url: "https://linkedin.com/in/shahzaib-abbasi-", name: "LinkedIn" },
    { icon: <FaTwitter />, url: "https://twitter.com/yourhandle", name: "Twitter" },
    { icon: <HiOutlineMail />, url: "mailto:mrhahzaibabbasi@gmail.com", name: "Email" }
  ];

const handleDownloadCV = () => {
  // Remove spaces from filename for better compatibility
  const fileName = 'ShahzaibAbbasi-Resume.pdf';
  
  fetch(resumePDF)
    .then(response => response.blob())
    .then(blob => {
      const url = window.URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = fileName;
      document.body.appendChild(link);
      link.click();
      window.URL.revokeObjectURL(url);
      document.body.removeChild(link);
    })
    .catch(() => {
      // Fallback if fetch fails
      window.open(resumePDF, '_blank');
    });
};

// Helper function for blob download
const fetchAndDownloadAsBlob = async (filePath, fileName) => {
  try {
    const response = await fetch(filePath);
    if (!response.ok) throw new Error('Failed to fetch');
    
    const blob = await response.blob();
    const blobUrl = window.URL.createObjectURL(blob);
    const blobLink = document.createElement('a');
    blobLink.href = blobUrl;
    blobLink.download = fileName;
    document.body.appendChild(blobLink);
    blobLink.click();
    
    // Cleanup
    setTimeout(() => {
      window.URL.revokeObjectURL(blobUrl);
      document.body.removeChild(blobLink);
    }, 100);
  } catch (error) {
    console.error('Blob download failed:', error);
    // Final fallback - Google Drive
   window.open('https://drive.google.com/uc?export=download&id=YOUR_ACTUAL_FILE_ID', '_blank');
  }
};
  return (
    <>
    <section 
      id="home" 
      className="relative min-h-screen flex items-center justify-center overflow-hidden px-4 sm:px-6 lg:px-8"
      style={{
        backgroundColor: theme === 'dark' ? '#111827' : '#0a192f' // Changed background colors here
      }}
    >
      {/* Animated background elements */}
      <div className="absolute inset-0 overflow-hidden">
        {[...Array(20)].map((_, i) => (
          <motion.div
            key={i}
            className={`absolute rounded-full ${
              theme === 'dark' ? 'bg-indigo-900/20' : 'bg-indigo-100/50'
            }`}
            initial={{
              x: Math.random() * 100 - 50,
              y: Math.random() * 100 - 50,
              scale: Math.random() * 0.5 + 0.5,
              opacity: 0
            }}
            animate={{
              x: Math.random() * 500 - 250,
              y: Math.random() * 500 - 250,
              opacity: 0.3
            }}
            transition={{
              duration: Math.random() * 20 + 10,
              repeat: Infinity,
              repeatType: "reverse"
            }}
            style={{
              width: `${Math.random() * 200 + 50}px`,
              height: `${Math.random() * 200 + 50}px`,
            }}
          />
        ))}
      </div>

      {/* Rest of the code remains exactly the same */}
      {/* Content container */}
      <div className="max-w-7xl mx-auto w-full relative z-10 py-20">
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-12 items-center">
          {/* Text content */}
          <motion.div
            initial={{ opacity: 0, y: 50 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ duration: 0.8 }}
            className="text-center lg:text-left"
          >
            <motion.div 
              className={`inline-block px-4 py-2 rounded-full mb-6 ${
                theme === 'dark' ? 'bg-indigo-900/30 text-indigo-300' : 'bg-indigo-100 text-indigo-600'
              }`}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.2 }}
            >
              <span className="font-medium">Full Stack Developer</span>
            </motion.div>

            <motion.h1 
              className={`text-5xl sm:text-6xl md:text-7xl font-bold mb-4 leading-tight ${
                theme === 'dark' ? 'text-white' : 'text-gray-900'
              }`}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.4 }}
            >
              <span className="block">Hi, I'm</span>
              <span className={`block bg-clip-text text-transparent bg-gradient-to-r ${
                theme === 'dark' 
                  ? 'from-indigo-400 to-purple-400' 
                  : 'from-indigo-600 to-purple-600'
              }`}>
                Shahzaib Abbasi
              </span>
            </motion.h1>
            
            <motion.h2
              className={`text-2xl sm:text-3xl md:text-4xl font-medium mb-6 min-h-[3.5rem] ${
                theme === 'dark' ? 'text-gray-300' : 'text-gray-600'
              }`}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.6 }}
            >
              <TypeAnimation
                sequence={[
                  'I build web applications',
                  1500,
                  'I create responsive UIs',
                  1500,
                  'I develop APIs',
                  1500,
                  'I solve problems',
                  1500,
                ]}
                speed={30}
                style={{ display: 'inline-block' }}
                repeat={Infinity}
              />
            </motion.h2>
            
            <motion.p
              className={`text-lg md:text-xl mb-8 max-w-2xl mx-auto lg:mx-0 ${
                theme === 'dark' ? 'text-gray-400' : 'text-gray-600'
              }`}
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 0.8 }}
            >
              Specializing in modern JavaScript frameworks and cloud technologies to deliver high-performance, scalable web applications with exceptional user experiences.
            </motion.p>
            
            <motion.div
              className="flex flex-col sm:flex-row gap-4 justify-center lg:justify-start mb-12"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 1 }}
            >
              <motion.a
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                href="#contact"
                className={`px-8 py-4 rounded-lg font-medium shadow-lg transition-all ${
                  theme === 'dark'
                    ? 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-700 hover:to-purple-700 text-white'
                    : 'bg-gradient-to-r from-indigo-600 to-purple-600 hover:from-indigo-700 hover:to-purple-700 text-white'
                }`}
              >
                Get In Touch
              </motion.a>
              <motion.button
                whileHover={{ scale: 1.05 }}
                whileTap={{ scale: 0.95 }}
                onClick={handleDownloadCV}
                className={`px-8 py-4 rounded-lg font-medium shadow-lg transition-all flex items-center gap-2 ${
                  theme === 'dark'
                    ? 'bg-gray-800 hover:bg-gray-700 text-white'
                    : 'bg-white hover:bg-gray-100 text-gray-900 border border-gray-300'
                }`}
              >
                <FaDownload /> Download CV
              </motion.button>
            </motion.div>

            {/* Social links */}
            <motion.div
              className="flex justify-center lg:justify-start gap-4"
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              transition={{ delay: 1.2 }}
            >
              {socialLinks.map((social, index) => (
                <motion.a
                  key={index}
                  href={social.url}
                  target="_blank"
                  rel="noopener noreferrer"
                  className={`p-3 rounded-full text-xl ${
                    theme === 'dark'
                      ? 'bg-gray-800 hover:bg-gray-700 text-indigo-400 hover:text-indigo-300'
                      : 'bg-white hover:bg-gray-100 text-indigo-600 hover:text-indigo-700 shadow-md'
                  } transition-all`}
                  whileHover={{ y: -5 }}
                  whileTap={{ scale: 0.9 }}
                  aria-label={social.name}
                >
                  {social.icon}
                </motion.a>
              ))}
            </motion.div>
          </motion.div>
          
          {/* Hero image */}
          <motion.div
            initial={{ opacity: 0, scale: 0.8 }}
            animate={{ opacity: 1, scale: 1 }}
            transition={{ duration: 0.8, delay: 0.4 }}
            className="relative flex justify-center"
          >
            <div className="relative">
              {/* Main image */}
              <div className={`relative w-72 h-72 sm:w-80 sm:h-80 md:w-96 md:h-96 rounded-2xl overflow-hidden ${
                theme === 'dark' 
                  ? 'ring-2 ring-indigo-500/30 shadow-2xl' 
                  : 'ring-2 ring-indigo-200 shadow-xl'
              }`}>
                <img 
                  src={heroImage} 
                  alt="Shahzaib Abbasi" 
                  className="w-full h-full object-cover"
                />
                <div className={`absolute inset-0 ${
                  theme === 'dark' 
                    ? 'bg-indigo-900/10' 
                    : 'bg-indigo-100/10'
                }`}></div>
              </div>

              {/* Decorative elements */}
              <motion.div
                className={`absolute -top-8 -left-8 w-32 h-32 rounded-full ${
                  theme === 'dark' ? 'bg-indigo-900/30' : 'bg-indigo-100/70'
                } -z-10`}
                animate={{
                  scale: [1, 1.1, 1],
                  rotate: [0, 10, 0]
                }}
                transition={{
                  duration: 8,
                  repeat: Infinity,
                  repeatType: "reverse"
                }}
              />
              <motion.div
                className={`absolute -bottom-8 -right-8 w-40 h-40 rounded-3xl ${
                  theme === 'dark' ? 'bg-purple-900/20' : 'bg-purple-100/70'
                } -z-10`}
                animate={{
                  scale: [1, 1.05, 1],
                  rotate: [0, -5, 0]
                }}
                transition={{
                  duration: 10,
                  repeat: Infinity,
                  repeatType: "reverse"
                }}
              />

              {/* Floating tech stack */}
              <motion.div
                className={`absolute -left-8 top-1/2 px-4 py-2 rounded-full shadow-md ${
                  theme === 'dark' ? 'bg-gray-800 text-indigo-300' : 'bg-white text-indigo-600'
                }`}
                initial={{ x: -20, opacity: 0 }}
                animate={{ x: 0, opacity: 1 }}
                transition={{ delay: 0.8 }}
                whileHover={{ scale: 1.05 }}
              >
                <span className="font-medium">React.js</span>
              </motion.div>

              <motion.div
                className={`absolute -right-8 top-1/3 px-4 py-2 rounded-full shadow-md ${
                  theme === 'dark' ? 'bg-gray-800 text-purple-300' : 'bg-white text-purple-600'
                }`}
                initial={{ x: 20, opacity: 0 }}
                animate={{ x: 0, opacity: 1 }}
                transition={{ delay: 1 }}
                whileHover={{ scale: 1.05 }}
              >
                <span className="font-medium">Node.js</span>
              </motion.div>

              <motion.div
                className={`absolute -bottom-8 left-1/4 px-4 py-2 rounded-full shadow-md ${
                  theme === 'dark' ? 'bg-gray-800 text-blue-300' : 'bg-white text-blue-600'
                }`}
                initial={{ y: 20, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                transition={{ delay: 1.2 }}
                whileHover={{ scale: 1.05 }}
              >
                <span className="font-medium">MongoDB</span>
              </motion.div>
            </div>
          </motion.div>
        </div>
      </div>
      
      {/* Scroll indicator */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 1.5 }}
        className="absolute bottom-8 left-1/2 transform -translate-x-1/2"
      >
        <motion.a
          href="#about"
          className={`p-3 rounded-full ${
            theme === 'dark' 
              ? 'bg-gray-800 text-indigo-400 shadow-lg' 
              : 'bg-white text-indigo-600 shadow-md'
          } transition-all`}
          animate={{ y: [0, 10, 0] }}
          transition={{ repeat: Infinity, duration: 2 }}
          aria-label="Scroll down"
        >
          <svg 
            xmlns="http://www.w3.org/2000/svg" 
            className="h-6 w-6" 
            fill="none" 
            viewBox="0 0 24 24" 
            stroke="currentColor"
          >
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 14l-7 7m0 0l-7-7m7 7V3" />
          </svg>
        </motion.a>
      </motion.div>



     

    </section>
    
            {/* Animated Services */}
      <Services theme="dark" />


          <StatsCounter theme="dark" /> 


          <TechCarousel theme="dark" /> 


          <ProjectShowcase theme="dark" /> 

          <Testimonials theme="dark"/>

          <ContactCTA theme="dark" />

    </>
    
  );
};

export default Home;