// src/components/TechCarousel.jsx
import { motion } from 'framer-motion';
import { useEffect, useRef, useState } from 'react';
import { 
  SiReact, 
  SiNodedotjs, 
  SiTailwindcss, 
  SiGit, 
  SiMongodb,
  SiExpress,
  SiTypescript,
  SiNextdotjs,
  SiFirebase,
  SiDocker
} from 'react-icons/si';

const TechCarousel = ({ theme }) => {
  const techStack = [
    { icon: <SiReact size={40} />, name: 'React' },
    { icon: <SiNodedotjs size={40} />, name: 'Node.js' },
    { icon: <SiTailwindcss size={40} />, name: 'Tailwind CSS' },
    { icon: <SiGit size={40} />, name: 'Git' },
    { icon: <SiMongodb size={40} />, name: 'MongoDB' },
    { icon: <SiExpress size={40} />, name: 'Express' },
    { icon: <SiTypescript size={40} />, name: 'TypeScript' },
    { icon: <SiNextdotjs size={40} />, name: 'Next.js' },
    { icon: <SiFirebase size={40} />, name: 'Firebase' },
    { icon: <SiDocker size={40} />, name: 'Docker' }
  ];

  const [width, setWidth] = useState(0);
  const carousel = useRef();
  const [isHovered, setIsHovered] = useState(false);

  useEffect(() => {
    setWidth(carousel.current.scrollWidth - carousel.current.offsetWidth);
  }, []);

  useEffect(() => {
    if (!isHovered) {
      const interval = setInterval(() => {
        if (carousel.current) {
          carousel.current.scrollLeft += 1;
          if (carousel.current.scrollLeft >= width) {
            carousel.current.scrollLeft = 0;
          }
        }
      }, 30);
      return () => clearInterval(interval);
    }
  }, [width, isHovered]);

  return (
    <section className={`py-12 ${theme === 'dark' ? 'bg-gray-800' : 'bg-gray-100'}`}>
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center mb-12">
          <h2 className={`text-3xl md:text-4xl font-bold mb-4 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
            Tech Stack
          </h2>
          <div className={`w-20 h-1 mx-auto mb-6 ${theme === 'dark' ? 'bg-indigo-500' : 'bg-indigo-600'}`}></div>
          <p className={`text-lg ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
            Technologies I work with daily
          </p>
        </div>

        <motion.div 
          ref={carousel} 
          className="overflow-hidden cursor-grab"
          onMouseEnter={() => setIsHovered(true)}
          onMouseLeave={() => setIsHovered(false)}
        >
          <motion.div 
            drag="x" 
            dragConstraints={{ right: 0, left: -width }}
            className="flex gap-8 py-4"
          >
            {[...techStack, ...techStack].map((tech, index) => (
              <motion.div
                key={index}
                className={`flex flex-col items-center justify-center p-6 rounded-xl shadow-md ${
                  theme === 'dark' ? 'bg-gray-700' : 'bg-white'
                }`}
                whileHover={{ 
                  scale: 1.1,
                  boxShadow: theme === 'dark' 
                    ? '0 10px 25px -5px rgba(99, 102, 241, 0.3)' 
                    : '0 10px 25px -5px rgba(79, 70, 229, 0.3)'
                }}
                whileTap={{ scale: 0.95 }}
              >
                <div className={`text-4xl mb-2 ${
                  theme === 'dark' ? 'text-gray-200' : 'text-gray-700'
                }`}>
                  {tech.icon}
                </div>
                <span className={`font-medium ${
                  theme === 'dark' ? 'text-gray-300' : 'text-gray-600'
                }`}>
                  {tech.name}
                </span>
              </motion.div>
            ))}
          </motion.div>
        </motion.div>
      </div>
    </section>
  );
};

export default TechCarousel;