// src/components/StatsCounter.jsx
import { motion } from 'framer-motion';
import { FiAward, FiUsers, FiClock, FiCode, FiLayers, FiCpu } from 'react-icons/fi';
import { useEffect, useRef, useState } from 'react';

const StatsCounter = ({ theme }) => {
  const statsData = [
    {
      icon: <FiAward className="text-4xl" />,
      value: 10,
      suffix: '+',
      label: 'Projects Completed',
      color: 'from-indigo-500 to-blue-500'
    },
    {
      icon: <FiUsers className="text-4xl" />,
      value: 5,
      suffix: '+',
      label: 'Happy Clients',
      color: 'from-green-500 to-teal-500'
    },
    {
      icon: <FiClock className="text-4xl" />,
      value: 1.5,
      suffix: '+',
      label: 'Years Experience',
      color: 'from-purple-500 to-pink-500'
    },
    {
      icon: <FiCode className="text-4xl" />,
      value: 100,
      suffix: '+',
      label: 'GitHub Commits',
      color: 'from-yellow-500 to-orange-500'
    }
  ];

  const [countersStarted, setCountersStarted] = useState(false);
  const statsRef = useRef(null);

  useEffect(() => {
    const observer = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) {
          setCountersStarted(true);
        }
      },
      { threshold: 0.5 }
    );

    if (statsRef.current) {
      observer.observe(statsRef.current);
    }

    return () => {
      if (statsRef.current) {
        observer.unobserve(statsRef.current);
      }
    };
  }, []);

  const Counter = ({ end, suffix }) => {
    const [count, setCount] = useState(0);
    
    useEffect(() => {
      if (!countersStarted) return;
      
      let start = 0;
      const duration = 2000;
      const increment = end / (duration / 16);
      
      const timer = setInterval(() => {
        start += increment;
        if (start >= end) {
          setCount(end);
          clearInterval(timer);
        } else {
          setCount(Math.ceil(start));
        }
      }, 16);

      return () => clearInterval(timer);
    }, [countersStarted, end]);

    return (
      <span className="text-5xl font-bold">
        {count}{suffix}
      </span>
    );
  };

  return (
    <section 
      ref={statsRef}
      className={`py-16 ${theme === 'dark' ? 'bg-gray-900' : 'bg-gray-50'}`}
      id="stats"
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="text-center mb-12"
        >
          <h2 className={`text-3xl md:text-4xl font-bold mb-4 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
            Key Highlights
          </h2>
          <div className={`w-20 h-1 mx-auto mb-6 ${theme === 'dark' ? 'bg-indigo-500' : 'bg-indigo-600'}`}></div>
          <p className={`text-lg ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
            Quantifying my impact through measurable achievements
          </p>
        </motion.div>

        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
          {statsData.map((stat, index) => (
            <motion.div
              key={index}
              initial={{ opacity: 0, y: 50 }}
              animate={{ opacity: 1, y: 0 }}
              transition={{ duration: 0.5, delay: index * 0.1 }}
              whileHover={{ scale: 1.05 }}
              className={`rounded-xl p-6 shadow-lg ${
                theme === 'dark' ? 'bg-gray-800' : 'bg-white'
              }`}
            >
              <div className={`flex items-center justify-center w-16 h-16 rounded-full mb-4 bg-gradient-to-r ${stat.color} text-white mx-auto`}>
                {stat.icon}
              </div>
              <div className="text-center">
                <div className={`mb-2 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
                  <Counter end={stat.value} suffix={stat.suffix} />
                </div>
                <h3 className={`text-lg font-medium ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
                  {stat.label}
                </h3>
              </div>
            </motion.div>
          ))}
        </div>
      </div>
    </section>
  );
};

export default StatsCounter;