import { motion } from 'framer-motion';
import { FiCode, FiServer, FiCpu, FiDatabase, FiSmartphone, FiLayers } from 'react-icons/fi';

const Services = ({ theme }) => {
  const services = [
    {
      icon: <FiCode size={28} />,
      title: "Frontend Development",
      description: "Building beautiful, responsive interfaces with modern technologies",
      skills: "React, Next.js, Tailwind CSS, TypeScript",
      color: "bg-indigo-100 text-indigo-600",
      darkColor: "bg-indigo-900/30 text-indigo-300"
    },
    {
      icon: <FiServer size={28} />,
      title: "Backend Development",
      description: "Robust server-side solutions and API development",
      skills: "Node.js, Express, Django, REST APIs",
      color: "bg-blue-100 text-blue-600",
      darkColor: "bg-blue-900/30 text-blue-300"
    },
    {
      icon: <FiCpu size={28} />,
      title: "Full Stack Solutions",
      description: "End-to-end web application development",
      skills: "MERN Stack, PostgreSQL, Authentication",
      color: "bg-purple-100 text-purple-600",
      darkColor: "bg-purple-900/30 text-purple-300"
    },
    {
      icon: <FiDatabase size={28} />,
      title: "Database Design",
      description: "Efficient data storage and management solutions",
      skills: "MongoDB, MySQL, Firebase, ORMs",
      color: "bg-teal-100 text-teal-600",
      darkColor: "bg-teal-900/30 text-teal-300"
    },
    {
      icon: <FiSmartphone size={28} />,
      title: "Mobile Responsive",
      description: "Flawless experiences across all devices",
      skills: "Responsive Design, PWA, Media Queries",
      color: "bg-green-100 text-green-600",
      darkColor: "bg-green-900/30 text-green-300"
    },
    {
      icon: <FiLayers size={28} />,
      title: "API Integration",
      description: "Connecting your app with third-party services",
      skills: "GraphQL, Axios, WebSockets, OAuth",
      color: "bg-orange-100 text-orange-600",
      darkColor: "bg-orange-900/30 text-orange-300"
    }
  ];

  const container = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.1
      }
    }
  };

  const item = {
    hidden: { y: 20, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: {
        duration: 0.5
      }
    }
  };

  return (
    <section 
      id="services" 
      className={`relative py-20 ${theme === 'dark' ? 'bg-gray-900' : 'bg-gray-50'}`}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Section header */}
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="text-center mb-16"
        >
          <h2 className={`text-3xl sm:text-4xl font-bold mb-4 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
            What I Do
          </h2>
          <div className={`w-20 h-1 mx-auto mb-6 ${theme === 'dark' ? 'bg-indigo-500' : 'bg-indigo-600'}`}></div>
          <p className={`text-lg max-w-2xl mx-auto ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
            Comprehensive web development services to bring your ideas to life
          </p>
        </motion.div>

        {/* Services grid */}
        <motion.div
          variants={container}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-100px" }}
          className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"
        >
          {services.map((service, index) => (
            <motion.div
              key={index}
              variants={item}
              whileHover={{ y: -10 }}
              className={`rounded-xl overflow-hidden shadow-lg transition-all duration-300 ${
                theme === 'dark' ? 'bg-gray-800 hover:bg-gray-700' : 'bg-white hover:bg-gray-50'
              }`}
            >
              <div className="p-6">
                <div className={`inline-flex items-center justify-center p-3 rounded-full mb-4 ${
                  theme === 'dark' ? service.darkColor : service.color
                }`}>
                  {service.icon}
                </div>
                <h3 className={`text-xl font-bold mb-2 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
                  {service.title}
                </h3>
                <p className={`mb-4 ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
                  {service.description}
                </p>
                <div className={`px-3 py-2 rounded-md text-sm font-medium ${
                  theme === 'dark' ? 'bg-gray-700 text-gray-200' : 'bg-gray-100 text-gray-700'
                }`}>
                  {service.skills}
                </div>
              </div>
            </motion.div>
          ))}
        </motion.div>

        {/* Decorative elements */}
        <div className="absolute top-0 left-0 w-full overflow-hidden -z-10">
          {[...Array(10)].map((_, i) => (
            <motion.div
              key={i}
              className={`absolute rounded-full ${
                theme === 'dark' ? 'bg-indigo-900/20' : 'bg-indigo-100/50'
              }`}
              initial={{
                x: Math.random() * 1000 - 500,
                y: Math.random() * 100 - 50,
                scale: Math.random() * 0.5 + 0.5,
                opacity: 0
              }}
              animate={{
                y: Math.random() * 100 - 50,
                opacity: 0.3
              }}
              transition={{
                duration: Math.random() * 20 + 10,
                repeat: Infinity,
                repeatType: "reverse"
              }}
              style={{
                width: `${Math.random() * 200 + 50}px`,
                height: `${Math.random() * 200 + 50}px`,
              }}
            />
          ))}
        </div>
      </div>
    </section>
  );
};

export default Services;