// src/components/Testimonials.jsx
import { motion } from 'framer-motion';
import { FaQuoteLeft } from 'react-icons/fa';

const Testimonials = ({ theme }) => {
  const testimonials = [
    {
      id: 1,
      quote: "Shahzaib delivered exactly what I asked for — super professional! The project was completed ahead of schedule with excellent communication throughout.",
      name: "John Doe",
      role: "CEO, TechStart Inc.",
      avatar: "/images/client1.jpg"
    },
    {
      id: 2,
      quote: "Working with Shahzaib was a game-changer for our business. His technical expertise and problem-solving skills exceeded our expectations.",
      name: "Sarah Johnson",
      role: "Product Manager, InnovateCo",
      avatar: "/images/client2.jpg"
    },
    {
      id: 3,
      quote: "The best developer I've worked with. Shahzaib understood our complex requirements and delivered a flawless solution.",
      name: "Michael Chen",
      role: "CTO, DigitalSolutions",
      avatar: "/images/client3.jpg"
    }
  ];

  const container = {
    hidden: { opacity: 0 },
    visible: {
      opacity: 1,
      transition: {
        staggerChildren: 0.2
      }
    }
  };

  const item = {
    hidden: { y: 50, opacity: 0 },
    visible: {
      y: 0,
      opacity: 1,
      transition: {
        duration: 0.6
      }
    }
  };

  return (
    <section className={`py-20 ${theme === 'dark' ? 'bg-gray-800' : 'bg-gray-100'}`} id="testimonials">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <motion.div
          initial={{ opacity: 0, y: 20 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ duration: 0.5 }}
          className="text-center mb-16"
        >
          <h2 className={`text-3xl sm:text-4xl font-bold mb-4 ${theme === 'dark' ? 'text-white' : 'text-gray-900'}`}>
            Client Testimonials
          </h2>
          <div className={`w-20 h-1 mx-auto mb-6 ${theme === 'dark' ? 'bg-indigo-500' : 'bg-indigo-600'}`}></div>
          <p className={`text-lg max-w-2xl mx-auto ${theme === 'dark' ? 'text-gray-300' : 'text-gray-600'}`}>
            What my clients say about working with me
          </p>
        </motion.div>

        <motion.div
          variants={container}
          initial="hidden"
          whileInView="visible"
          viewport={{ once: true, margin: "-100px" }}
          className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8"
        >
          {testimonials.map((testimonial) => (
            <motion.div
              key={testimonial.id}
              variants={item}
              whileHover={{ y: -10 }}
              className={`p-8 rounded-xl ${
                theme === 'dark' ? 'bg-gray-700' : 'bg-white'
              } shadow-lg`}
            >
              <div className={`mb-6 ${
                theme === 'dark' ? 'text-indigo-400' : 'text-indigo-600'
              }`}>
                <FaQuoteLeft size={24} />
              </div>
              <p className={`text-lg italic mb-6 ${
                theme === 'dark' ? 'text-gray-300' : 'text-gray-600'
              }`}>
                "{testimonial.quote}"
              </p>
              <div className="flex items-center">
                <img
                  src={testimonial.avatar}
                  alt={testimonial.name}
                  className="w-12 h-12 rounded-full object-cover mr-4"
                />
                <div>
                  <h4 className={`font-bold ${
                    theme === 'dark' ? 'text-white' : 'text-gray-900'
                  }`}>
                    {testimonial.name}
                  </h4>
                  <p className={`text-sm ${
                    theme === 'dark' ? 'text-gray-400' : 'text-gray-500'
                  }`}>
                    {testimonial.role}
                  </p>
                </div>
              </div>
            </motion.div>
          ))}
        </motion.div>
      </div>
    </section>
  );
};

export default Testimonials;